                    SELECT "IDConsorcio", 'Torre Alfa Norte', 'EDIFICIO', 'Avenida Norte 100' 
                    FROM "PB_Consorcio" WHERE "Cuit" = '11111111111' 
                    ON CONFLICT ("IDConsorcio", "Nombre") DO NOTHING;

