                    SELECT "IDConsorcio", 'Barrio Beta Sur', 'BARRIO_PRIVADO', 'Ruta Sur 200' 
                    FROM "PB_Consorcio" WHERE "Cuit" = '22222222222' 
                    ON CONFLICT ("IDConsorcio", "Nombre") DO NOTHING;
                
    END IF;
